// The Bitcoin whitepaper as a poster (18.5 by 24.5 inches), rendered from the maintainer's PDF at 167 dpi, its greys
// quantised to the sixteen steps the page's own boards are drawn in, and set into the library's monolith (scene-hub.js).
// One picture, a data URL, so the portable page needs no request for it.
(() => {
  "use strict";
  const BL = window.BL = window.BL || {};
  BL.whitepaperPoster = { poster: "data:image/png;base64," };
})();
